import cyclopts

def status():
    """Show the current status"""
    print("Status: OK")

app = cyclopts.App(default=status)

@app.command
def start():
    """Start the service"""
    print("Service started")

@app.command
def stop():
    """Stop the service"""
    print("Service stopped")

if __name__ == "__main__":
    app()
